  --color-warning-11: var(--orange-11);
  --color-warning-12: var(--orange-12);

  /* ─── Palette / Info → cyan ─────────────────────────────────────────────── */
  --color-info-1: var(--cyan-1);
  --color-info-2: var(--cyan-2);
  --color-info-3: var(--cyan-3);
  --color-info-4: var(--cyan-4);
  --color-info-5: var(--cyan-5);
  --color-info-6: var(--cyan-6);
  --color-info-7: var(--cyan-7);
  --color-info-8: var(--cyan-8);
  --color-info-9: var(--cyan-9);
  --color-info-10: var(--cyan-10);
  --color-info-11: var(--cyan-11);
  --color-info-12: var(--cyan-12);

  /* ─── Typography / Font Family ──────────────────────────────────────────── */
  --font-header: "Poppins", ui-sans-serif, system-ui, sans-serif;
  --font-body: "Inter", ui-sans-serif, system-ui, sans-serif;
  --font-mono: var(--font-geist-mono), ui-monospace, monospace;

  /* ─── Typography / Font Size → Type Scale / Medium ──────────────────────── */
  --text-display-1: var(--solar-type-medium-1);
  --text-display-2: var(--solar-type-medium-2);
  --text-display-3: var(--solar-type-medium-3);
  --text-display-4: var(--solar-type-medium-4);
  --text-display-5: var(--solar-type-medium-5);
  --text-display-6: var(--solar-type-medium-6);

  --text-title-1: var(--solar-type-medium-4);
  --text-title-2: var(--solar-type-medium-5);
  --text-title-3: var(--solar-type-medium-6);
  --text-title-4: var(--solar-type-medium-7);
  --text-title-5: var(--solar-type-medium-8);
  --text-title-6: var(--solar-type-medium-9);

  --text-label: var(--solar-type-medium-10);
  --text-label-compact: var(--solar-type-medium-11);

  --text-body: var(--solar-type-medium-9);
  --text-body-compact: var(--solar-type-medium-10);

  --text-code: var(--solar-type-medium-9);
  --text-code-compact: var(--solar-type-medium-11);

  --text-avatar-fallback-sm: var(--solar-type-medium-11);

  /* ─── Layout / Field ────────────────────────────────────────────────────── */
  --radius-field-inner: calc(var(--spacing) * 1.5); /* Sizes/0,375 */
  --radius-field: calc(var(--spacing) * 3); /* Sizes/0,75 */
  --spacing-field-padding: calc(var(--spacing) * 1.5); /* Sizes/0,375 */
  --spacing-field: calc(var(--spacing) * 10); /* Sizes/2,5 */
  --spacing-field-gap: calc(var(--spacing) * 1); /* Sizes/0,25 */

  /* ─── Illustration / Shape ──────────────────────────────────────────────── */
  --solar-illustration-focal: "Blob";
  --solar-illustration-detail: "Circle";
}

/* ============================================================================
 * SolarUI — point d'entrée du design system
 * ----------------------------------------------------------------------------
 * Ce fichier assemble les trois collections de variables Figma et déclare leurs
 * tokens auprès de Tailwind. C'est le seul fichier à importer dans globals.css :
 *
 *     @import "tailwindcss";
 *     @import "./theme.css";
 *
 * Chaîne de dépendance, identique à Figma :
 *
 *     radix.css   (Mode)    couleurs primitives, modes Light / Dark
 *     screen.css  (Screen)  nombres, modes Desktop / Mobile
 *          └──────────────► themes/*.css (Theme)  tokens sémantiques
 *
 * Trois axes indépendants se combinent librement :
 *   • clair / sombre     → classe `.dark` sur <html>
 *   • desktop / mobile   → automatique, breakpoint 48rem
 *   • Stellar / Trevia   → attribut `data-theme` sur <html>
 * ========================================================================== */

@import "./radix.css";
@import "./screen.css";

/* ─── Thèmes ──────────────────────────────────────────────────────────────────
 * Tous les thèmes importés sont disponibles à tout moment via
 * `<html data-theme="…">`.
 *
 * L'ORDRE DE CES LIGNES N'A AUCUNE IMPORTANCE. Turbopack réordonne les `@import`
 * entre `next dev` et `next build` : s'appuyer sur l'ordre donnerait un thème
 * par défaut différent selon le mode. Le thème par défaut est donc désigné DANS
 * son propre fichier, par un sélecteur `:where(:root)` que lui seul porte.
 *
 * Défaut actuel : Stellar → themes/stellar.css
 * ------------------------------------------------------------------------- */

@import "./themes/stellar.css";
@import "./themes/trevia.css";

@custom-variant dark (&:is(.dark *));

/* ============================================================================
 * Constantes du système
 * ----------------------------------------------------------------------------
 * Tout ce qui est identique dans TOUS les thèmes. Les tokens qui varient d'un
 * thème à l'autre — palettes, polices, tailles de texte, Layout/Field — sont
 * déclarés dans le bloc `@theme` du thème par défaut (themes/stellar.css) et
 * n'apparaissent donc pas ici.
 *
 * Tailwind fusionne tous les blocs `@theme` du projet, d'où qu'ils viennent.
 * ========================================================================== */

@theme {
  /* ─── Hauteurs de ligne — valeurs réelles ───────────────────────────────────
   * Ni les hauteurs de ligne ni l'interlettrage ne sont des variables Figma :
   * ce sont des constantes du système, indépendantes du thème et de l'écran.
   * ------------------------------------------------------------------------ */
  --text-display-1--line-height: 1.2;
  --text-display-2--line-height: 1.2;
  --text-display-3--line-height: 1.3;
  --text-display-4--line-height: 1.3;
  --text-display-5--line-height: 1.3;
  --text-display-6--line-height: 1.3;
  --text-title-1--line-height: 1.3;
  --text-title-2--line-height: 1.3;
  --text-title-3--line-height: 1.3;
  --text-title-4--line-height: 1.3;
  --text-title-5--line-height: 1.3;
  --text-title-6--line-height: 1.3;
  --text-label--line-height: 1.4;
  --text-label-compact--line-height: 1.4;
  --text-body--line-height: 1.5;
  --text-body-compact--line-height: 1.5;
  --text-code--line-height: 1;
  --text-code-compact--line-height: 1;
  --text-avatar-fallback-sm--line-height: 1;

  /* ─── Interlettrage — valeurs réelles ───────────────────────────────────── */
  --tracking-display-tight: -0.02em;
  --tracking-display-normal: -0.01em;
  --tracking-display-loose: 0.01em;
  --tracking-label: 0.015em;
  --tracking-body: 0.005em;

  /* ─── Elevation — valeurs réelles, communes à tous les thèmes ───────────── */
  --shadow-xs: 0 1px 2px 0 var(--black-a1);
  --shadow-sm: 0 1px 2px 0 var(--black-a1), 0 1px 3px 0 var(--black-a1);
  --shadow-md: 0 2px 4px -2px var(--black-a1), 0 4px 8px -2px var(--black-a2);
  --shadow-lg: 0 4px 6px -2px var(--black-a1), 0 12px 16px -4px var(--black-a2);
  --shadow-xl: 0 8px 8px -4px var(--black-a1), 0 20px 24px -4px var(--black-a2);
  --shadow-2xl: 0 24px 48px -12px var(--black-a4);
  --shadow-3xl: 0 32px 64px -12px var(--black-a3);

  /* ─── Animations — valeurs réelles ──────────────────────────────────────── */
  --animate-accordion-down: accordion-down 0.2s ease-out;
  --animate-accordion-up: accordion-up 0.2s ease-out;
}

@keyframes accordion-down {
  from { height: 0; }
  to   { height: var(--radix-accordion-content-height); }
}

@keyframes accordion-up {
  from { height: var(--radix-accordion-content-height); }
  to   { height: 0; }
}

/* ============================================================================
 * Tokens dérivés
 * ----------------------------------------------------------------------------
 * Les noms shadcn sont conservés pour les composants pas encore migrés. Étant
 * dérivés des tokens de thème, ils suivent `data-theme` sans traitement.
 * ========================================================================== */

:root {
  --background: var(--color-default-1);
  --foreground: var(--color-default-12);
  --card: var(--color-default-2);
  --card-foreground: var(--color-default-12);
  --popover: var(--color-default-2);
  --popover-foreground: var(--color-default-12);
  --primary: var(--color-brand-9);
  --primary-foreground: var(--color-brand-1);
  --secondary: var(--color-default-3);
  --secondary-foreground: var(--color-default-12);
  --muted: var(--color-default-3);
  --muted-foreground: var(--color-default-11);
  --accent: var(--color-default-3);
  --accent-foreground: var(--color-default-12);
  --destructive: var(--color-error-9);
  --destructive-foreground: var(--color-error-1);
  --border: var(--color-default-6);
  --input: var(--color-default-7);
  --ring: var(--color-brand-8);
  --radius: var(--radius-field);

  /* ─── Sidebar ───────────────────────────────────────────────────────────── */
  --sidebar: var(--color-default-2);
  --sidebar-foreground: var(--color-default-11);
  --sidebar-primary: var(--color-brand-9);
  --sidebar-primary-foreground: var(--color-brand-1);
  --sidebar-accent: var(--color-default-3);
  --sidebar-accent-foreground: var(--color-default-12);
  --sidebar-border: var(--color-default-6);
  --sidebar-ring: var(--color-brand-8);
}

@theme inline {
  --color-sidebar: var(--sidebar);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-ring: var(--sidebar-ring);
}

/* ============================================================================
 * Base
 * ========================================================================== */

@layer base {
  * {
    border-color: var(--color-default-6);
  }

  body {
    background-color: var(--color-default-1);
    color: var(--color-default-12);
    font-family: var(--font-body);
  }

  button:not(:disabled),
  [role="button"]:not(:disabled) {
    cursor: pointer;
  }

  /* ─── Input gradient border ─────────────────────────────────────────────── */
  [data-slot="input"] {
    background:
      linear-gradient(to top, var(--color-default-2), var(--color-default-1)) padding-box,
      linear-gradient(to bottom, var(--color-default-8), var(--color-default-6)) border-box;
    border-color: transparent;
  }

  [data-slot="input"]:disabled {
    background: var(--color-default-3);
  }

  [data-slot="input"]:focus-visible {
    background:
      linear-gradient(to top, var(--color-default-2), var(--color-default-1)) padding-box,
      linear-gradient(to bottom, var(--color-default-9), var(--color-default-8)) border-box;
  }

  [data-slot="input"][aria-invalid="true"] {
    background:
      linear-gradient(to top, var(--color-default-2), var(--color-default-1)) padding-box,
      linear-gradient(to bottom, var(--color-error-7), var(--color-error-7)) border-box;
  }
}
